 request: { id: string; actor_id: string; pet_id: string; request_hash: string; status: string; request_payload: Record<string, unknown>; source_context: { schema_version: number; run_id: string; page: number; parent: Record<string, unknown>; attachment_snapshot_id: string; attachment_payload_hash: string; attachment_observed_head_version: number; attachment_external_id: string; attachment_metadata: Record<string, unknown> } };
