  if(path==='/functions/v1/ezyvet-import'){if(state.stageCode)return r.fulfill({status:409,json:{error:state.stageCode}});if(state.failAfterStage)state.recoveryFails=true;state.nextPage++;state.running=false;return state.stageFails?r.fulfill({status:503,json:{error:'synthetic lost response'}}):r.fulfill({json:{run_id:run,review_only:true,status:'review_ready',next_page:state.nextPage}});}
