async function cleanupFixture(page:Page){
 const f=await fixture(page); f.state.fileReserveOnly=true;
 const state={saved:null as null|{attempt:Record<string,unknown>;receipt:Record<string,unknown>|null},lost:false,disabled:false,recoveryFails:false,calls:[] as Record<string,unknown>[]};
 await page.route('**/rest/v1/rpc/recover_ezyvet_attachment_cleanup',r=>state.recoveryFails?r.fulfill({status:503,json:{message:'synthetic unavailable'}}):r.fulfill({json:state.saved}));
 await page.route('**/rest/v1/rpc/list_ezyvet_attachment_cleanups',r=>r.fulfill({json:{request_id:r.request().postDataJSON().p_id,pet_id:pet,cleanups:state.saved?[{...state.saved,lease_active:!state.saved.receipt&&Date.parse(String(state.saved.attempt.lease_until))>Date.now()}]:[],has_more:false,next_cursor:null}}));
 await page.route('**/functions/v1/ezyvet-attachment-cleanup',r=>{
  const b=r.request().postDataJSON();state.calls.push(b);
  if(state.disabled)return r.fulfill({status:503,json:{error:'CLEANUP_DISABLED'}});
  const created=new Date(Date.now()-1000).toISOString();
  state.saved={attempt:{id:b.cleanup_id,request_id:b.request_id,actor_id:actor,pet_id:pet,request_hash:b.request_hash,intent_hash:'d'.repeat(64),created_at:created,lease_until:new Date(Date.now()+89000).toISOString()},receipt:{cleanup_id:b.cleanup_id,request_id:b.request_id,actor_id:actor,intent_hash:'d'.repeat(64),verified_absent_at:new Date().toISOString()}};
  return state.lost?r.fulfill({status:503,json:{error:'STORAGE_UNAVAILABLE'}}):r.fulfill({json:{status:'cleanup_recorded',request_id:b.request_id,cleanup_id:b.cleanup_id}});
 });
 await f.open();await f.section.getByRole('button',{name:'Prepare private file copy',exact:true}).click();await expect(f.section.getByRole('button',{name:'Capture file privately',exact:true})).toBeEnabled();await f.section.getByRole('button',{name:'Capture file privately',exact:true}).click();await expect(f.section.getByRole('button',{name:'Abandon file request',exact:true})).toBeEnabled();await f.section.getByRole('button',{name:'Abandon file request',exact:true}).click();await page.getByRole('button',{name:'Confirm file abandonment',exact:true}).click();await expect(f.section.getByRole('button',{name:'Clean up temporary file',exact:true})).toBeEnabled();return {...f,cleanup:state};
}
test('cleanup requires confirmation and recovers a lost completion reply',async({page})=>{const f=await cleanupFixture(page);f.cleanup.lost=true;await f.section.getByRole('button',{name:'Clean up temporary file',exact:true}).click();await page.getByRole('button',{name:'Keep temporary file',exact:true}).click();expect(f.cleanup.calls).toHaveLength(0);await f.section.getByRole('button',{name:'Clean up temporary file',exact:true}).click();await page.getByRole('button',{name:'Confirm temporary file cleanup',exact:true}).click();await expect(f.section.getByText(/This is a point-in-time receipt/)).toBeVisible();expect(f.cleanup.calls).toHaveLength(1);await expect(f.section.getByRole('button',{name:'Start another file request',exact:true})).toBeEnabled();});
test('disabled cleanup retains its identity for the same explicit retry',async({page})=>{const f=await cleanupFixture(page);f.cleanup.disabled=true;await f.section.getByRole('button',{name:'Clean up temporary file',exact:true}).click();await page.getByRole('button',{name:'Confirm temporary file cleanup',exact:true}).click();await expect(f.section.getByText('Temporary file cleanup is not commissioned. An administrator must finish server setup.',{exact:true})).toBeVisible();await expect(f.section.getByRole('button',{name:'Start another file request',exact:true})).toBeDisabled();f.cleanup.disabled=false;await f.section.getByRole('button',{name:'Retry original cleanup',exact:true}).click();await page.getByRole('button',{name:'Confirm temporary file cleanup',exact:true}).click();await expect(f.section.getByText(/This is a point-in-time receipt/)).toBeVisible();expect(f.cleanup.calls[0].cleanup_id).toBe(f.cleanup.calls[1].cleanup_id);});
test('cleanup reference survives reload and history repairs a lost local pointer',async({page})=>{const f=await cleanupFixture(page);await f.section.getByRole('button',{name:'Clean up temporary file',exact:true}).click();await page.getByRole('button',{name:'Confirm temporary file cleanup',exact:true}).click();await expect(f.section.getByText(/This is a point-in-time receipt/)).toBeVisible();await page.reload();await f.open();await f.section.getByRole('button',{name:'Recheck file request',exact:true}).click();await f.section.getByRole('button',{name:'Recheck cleanup attempt',exact:true}).click();await expect(f.section.getByText(/This is a point-in-time receipt/)).toBeVisible();await page.evaluate(()=>{for(const key of Object.keys(sessionStorage))if(key.startsWith('lrv-attachment-cleanup:'))sessionStorage.removeItem(key);});await page.reload();await f.open();await f.section.getByRole('button',{name:'Recheck file request',exact:true}).click();await f.section.getByRole('button',{name:/^Recover cleanup /}).click();await expect(f.section.getByText(/This is a point-in-time receipt/)).toBeVisible();expect(f.cleanup.calls).toHaveLength(1);});

