test('approval history keeps latest identity while paging through prior decisions',async({page})=>{
 const f=await capturedFixture(page);
 await page.route('**/rest/v1/rpc/list_ezyvet_attachment_record_versions',r=>{
  const b=r.request().postDataJSON(),old=!!b.p_before_id,request=f.state.fileRequest!.request;
  const {attachment_metadata: _metadata,...source}=request.source_context;void _metadata;
  const record={id:uid(old?90:91),actor_id:actor,request_id:request.id,pet_id:pet,animal_link_id:link,source_origin:'https://api.trial.ezyvet.com',source_site_uid:'synthetic-site',attachment_external_id:'701',request_hash:request.request_hash,capture_hash:'e'.repeat(64),source_context:source,title:old?'Original decision':'<script>Reviewed correction</script>',review_reason:'Synthetic original inspection',previous_record_id:old?null:uid(90),version:old?1:2,entry_method:'staff_reviewed_api_attachment_v1',record_hash:'f'.repeat(64),created_at:at};
  return r.fulfill({json:{request_id:request.id,pet_id:pet,animal_link_id:link,attachment_external_id:'701',latest_record_id:uid(91),records:[record],has_more:!old,next_cursor:old?null:{before_at:at,before_id:record.id}}});
 });
 const history=f.section.getByRole('region',{name:'API attachment approval history'});await history.getByRole('button',{name:'Recheck approval history',exact:true}).click();await expect(history.getByText('Version 2: <script>Reviewed correction</script>',{exact:true})).toBeVisible();await expect(history.getByText(/Latest saved approval/)).toBeVisible();await history.getByRole('button',{name:'Older approval versions',exact:true}).click();await expect(history.getByText('Version 1: Original decision',{exact:true})).toBeVisible();await expect(history.getByText(/Earlier approval version/)).toBeVisible();await expect(history.locator('script')).toHaveCount(0);
});
test('wrong-patient approval history is withheld',async({page})=>{const f=await capturedFixture(page);await page.route('**/rest/v1/rpc/list_ezyvet_attachment_record_versions',r=>r.fulfill({json:{request_id:f.state.fileRequest!.request.id,pet_id:uid(999),animal_link_id:link,attachment_external_id:'701',latest_record_id:null,records:[],has_more:false,next_cursor:null}}));const history=f.section.getByRole('region',{name:'API attachment approval history'});await history.getByRole('button',{name:'Recheck approval history',exact:true}).click();await expect(history.getByText('Approval history could not be verified. Recheck before making a review decision.',{exact:true})).toBeVisible();});
